="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/></svg><?= $user['is_blocked']?'Unblock':'Block' ?></button></form><form method="post"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="id" value="<?= $user['id'] ?>"><input type="hidden" name="action" value="role"><input type="hidden" name="role" value="<?= $user['role']==='admin'?'user':'admin' ?>"><button class="role-button"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7z"/><path d="m8 12 3 3 5-6"/></svg>Make <?= $user['role']==='admin'?'User':'Admin' ?></button></form><form method="post" class="delete-user-form" data-user-email="<?= e($user['email']) ?>"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="id" value="<?= $user['id'] ?>"><input type="hidden" name="action" value="delete"><button class="delete-user-button" type="submit"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/></svg>Delete</button></form></div><?php else: ?><span class="protected-account-badge"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>Protected account</span><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$users): ?><tr><td colspan="5" class="empty-state">No matching users.</td></tr><?php endif; ?></tbody></table></div></section>
